package main
import("context";"encoding/json";"fmt";"os";"github.com/jackc/pgx/v5/pgxpool")
func main(){ctx:=context.Background();db,e:=pgxpool.New(ctx,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer db.Close();rows,e:=db.Query(ctx,`with r as(select r.id,r.stream_id,r.status,r.cron_timezone,r.daily_window_start,r.daily_window_end,r.end_at,case when (r.end_at at time zone r.cron_timezone)::time<r.daily_window_end then ((r.end_at at time zone r.cron_timezone)::date-1) else (r.end_at at time zone r.cron_timezone)::date end final_date from recordings r where account_id=47 and mode='continuous' and end_at is not null) select r.id,r.stream_id,r.status,r.cron_timezone,r.daily_window_start::text,r.daily_window_end::text,r.end_at,r.final_date,count(j.id)filter(where j.status='pending'),count(j.id)filter(where j.status='leased' and j.lease_expires_at>now()),count(j.id)filter(where j.handoff_until>now()),(select count(*) from recording_upload_intents u where u.recording_id=r.id and u.status='pending' and u.expires_at>now()) from r left join recording_jobs j on j.recording_id=r.id where r.final_date between '2026-08-15' and '2026-08-18' group by r.id,r.stream_id,r.status,r.cron_timezone,r.daily_window_start,r.daily_window_end,r.end_at,r.final_date order by r.final_date,r.id`);if e!=nil{panic(e)};for rows.Next(){var id,sid int64;var st,tz,ds,de string;var end,day any;var pending,leased,handoff,intents int;if e=rows.Scan(&id,&sid,&st,&tz,&ds,&de,&end,&day,&pending,&leased,&handoff,&intents);e!=nil{panic(e)};b,_:=json.Marshal(map[string]any{"kind":"cohort","recording_id":id,"stream_id":sid,"status":st,"timezone":tz,"daily_start":ds,"daily_end":de,"end_at":end,"final_local_date":day,"pending":pending,"leased":leased,"handoff":handoff,"pending_intents":intents});fmt.Println(string(b))};rows.Close();rows,e=db.Query(ctx,`with r as(select r.id,r.stream_id,r.status,r.cron_timezone,r.daily_window_end,r.end_at,case when (r.end_at at time zone r.cron_timezone)::time<r.daily_window_end then ((r.end_at at time zone r.cron_timezone)::date-1) else (r.end_at at time zone r.cron_timezone)::date end final_date from recordings r where account_id=47 and mode='continuous' and end_at is not null)select id,stream_id,status,cron_timezone,final_date from r where final_date<'2026-08-15' order by final_date,id`);if e!=nil{panic(e)};for rows.Next(){var id,sid int64;var st,tz string;var day any;if e=rows.Scan(&id,&sid,&st,&tz,&day);e!=nil{panic(e)};b,_:=json.Marshal(map[string]any{"kind":"before","recording_id":id,"stream_id":sid,"status":st,"timezone":tz,"final_local_date":day});fmt.Println(string(b))}}
